import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> {'qty': int, 'active': bool}
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)

    for seq, o in enumerate(orders):
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            info = orders_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        orders_info[oid] = {'qty': qty, 'active': True}
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                sp, sseq, sid = sell_heap[0]
                sinfo = orders_info[sid]
                if not sinfo['active'] or sinfo['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ == 'market' or price >= sp:
                    trade_qty = min(remaining, sinfo['qty'])
                    trades.append([oid, sid, sp, trade_qty])
                    remaining -= trade_qty
                    sinfo['qty'] -= trade_qty
                    if sinfo['qty'] == 0:
                        sinfo['active'] = False
                        heapq.heappop(sell_heap)
                else:
                    break

            orders_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                orders_info[oid]['active'] = False

        else:  # side == 'sell'
            while remaining > 0 and buy_heap:
                bp_neg, bseq, bid = buy_heap[0]
                bp = -bp_neg
                binfo = orders_info[bid]
                if not binfo['active'] or binfo['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ == 'market' or price <= bp:
                    trade_qty = min(remaining, binfo['qty'])
                    trades.append([bid, oid, bp, trade_qty])
                    remaining -= trade_qty
                    binfo['qty'] -= trade_qty
                    if binfo['qty'] == 0:
                        binfo['active'] = False
                        heapq.heappop(buy_heap)
                else:
                    break

            orders_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(sell_heap, (price, seq, oid))
            else:
                orders_info[oid]['active'] = False

    return trades

